package com.shellsongs;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.function.IntConsumer;
import javax.swing.JComponent;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Paints the whole song as rows of note "chips". Each phrase starts a new row and long phrases wrap.
 * Played notes are dimmed, the next note is highlighted, and clicking a chip jumps to that note.
 */
class NoteSheetComponent extends JComponent
{
	private static final int CHIP_SIZE = 22;
	private static final int CHIP_GAP = 3;
	private static final int ROW_GAP = 5;
	private static final int PHRASE_GAP = 9;
	private static final int ARC = 6;

	private static final Color PLAYED_BG = ColorScheme.DARKER_GRAY_COLOR;
	private static final Color PLAYED_FG = ColorScheme.MEDIUM_GRAY_COLOR;
	private static final Color NEXT_BG = ColorScheme.BRAND_ORANGE;
	private static final Color NEXT_FG = Color.BLACK;
	/** The rest of a run of repeated notes: same shell, still to be clicked. */
	private static final Color RUN_BG = new Color(150, 95, 0);
	private static final Color RUN_FG = Color.WHITE;
	private static final Color UPCOMING_BG = ColorScheme.MEDIUM_GRAY_COLOR;
	private static final Color UPCOMING_FG = Color.WHITE;

	private Song song;
	private int position;
	/** Number of notes from {@code position} that are the same shell (the "click N times" run). */
	private int runLength = 1;
	private final IntConsumer onNoteClicked;

	/** Chip bounds from the last layout pass, indexed by note position. Used for click hit-testing. */
	private final List<Rectangle> chipBounds = new ArrayList<>();
	private int layoutWidth = -1;
	private int layoutHeight = 0;

	NoteSheetComponent(IntConsumer onNoteClicked)
	{
		this.onNoteClicked = onNoteClicked;
		setOpaque(false);
		setFont(FontManager.getRunescapeSmallFont());
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (song == null)
				{
					return;
				}
				for (int i = 0; i < chipBounds.size(); i++)
				{
					if (chipBounds.get(i).contains(e.getPoint()))
					{
						onNoteClicked.accept(i);
						return;
					}
				}
			}
		});
	}

	void setSong(Song song)
	{
		if (this.song == song)
		{
			return;
		}
		this.song = song;
		this.position = 0;
		layoutWidth = -1;
		revalidate();
		repaint();
	}

	void setPosition(int position, int runLength)
	{
		this.position = position;
		this.runLength = Math.max(1, runLength);
		repaint();
	}

	private int availableWidth()
	{
		int w = getWidth();
		if (w <= 0)
		{
			// Not laid out yet: assume the usual sidebar width minus PluginPanel padding.
			w = PluginPanel.PANEL_WIDTH - 2 * PluginPanel.BORDER_OFFSET;
		}
		return w;
	}

	/** Recomputes chip positions for the given width. Cheap, so it may run on every paint. */
	private void layoutChips(int width)
	{
		if (width == layoutWidth)
		{
			return;
		}
		layoutWidth = width;
		chipBounds.clear();

		if (song == null)
		{
			layoutHeight = 0;
			return;
		}

		int perRow = Math.max(1, (width + CHIP_GAP) / (CHIP_SIZE + CHIP_GAP));
		int y = 0;
		boolean firstPhrase = true;
		for (List<ShellNote> phrase : song.getPhrases())
		{
			if (!firstPhrase)
			{
				y += PHRASE_GAP;
			}
			firstPhrase = false;

			int col = 0;
			for (int i = 0; i < phrase.size(); i++)
			{
				if (col == perRow)
				{
					col = 0;
					y += CHIP_SIZE + ROW_GAP;
				}
				int x = col * (CHIP_SIZE + CHIP_GAP);
				chipBounds.add(new Rectangle(x, y, CHIP_SIZE, CHIP_SIZE));
				col++;
			}
			y += CHIP_SIZE + ROW_GAP;
		}
		layoutHeight = Math.max(0, y - ROW_GAP);
	}

	@Override
	public Dimension getPreferredSize()
	{
		int width = availableWidth();
		layoutChips(width);
		return new Dimension(width, layoutHeight);
	}

	@Override
	public Dimension getMaximumSize()
	{
		Dimension pref = getPreferredSize();
		return new Dimension(Integer.MAX_VALUE, pref.height);
	}

	@Override
	public void invalidate()
	{
		layoutWidth = -1;
		super.invalidate();
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		if (song == null)
		{
			return;
		}

		layoutChips(availableWidth());

		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

		Font font = getFont();
		g2.setFont(font);
		FontMetrics fm = g2.getFontMetrics();
		List<ShellNote> notes = song.getNotes();

		for (int i = 0; i < chipBounds.size() && i < notes.size(); i++)
		{
			Rectangle r = chipBounds.get(i);
			Color bg;
			Color fg;
			if (i < position)
			{
				bg = PLAYED_BG;
				fg = PLAYED_FG;
			}
			else if (i == position)
			{
				bg = NEXT_BG;
				fg = NEXT_FG;
			}
			else if (i < position + runLength)
			{
				bg = RUN_BG;
				fg = RUN_FG;
			}
			else
			{
				bg = UPCOMING_BG;
				fg = UPCOMING_FG;
			}

			g2.setColor(bg);
			g2.fillRoundRect(r.x, r.y, r.width, r.height, ARC, ARC);

			String label = notes.get(i).getLabel();
			int tx = r.x + (r.width - fm.stringWidth(label)) / 2;
			int ty = r.y + (r.height - fm.getHeight()) / 2 + fm.getAscent();
			g2.setColor(fg);
			g2.drawString(label, tx, ty);
		}

		g2.dispose();
	}
}

package com.shellsongs;

/**
 * An immutable snapshot of where the player is in the selected song. Produced on the client thread
 * or the Swing thread and safely readable from either.
 */
public final class PlaybackState
{
	public static final PlaybackState EMPTY = new PlaybackState(null, 0, null, false);

	private final Song song;
	private final int position;
	private final String feedback;
	private final boolean feedbackIsError;

	public PlaybackState(Song song, int position, String feedback, boolean feedbackIsError)
	{
		this.song = song;
		this.position = position;
		this.feedback = feedback;
		this.feedbackIsError = feedbackIsError;
	}

	/** The selected song, or null when none is selected. */
	public Song getSong()
	{
		return song;
	}

	/** Index of the next note to play. Equal to {@code song.size()} when the song is finished. */
	public int getPosition()
	{
		return position;
	}

	/** Short message to show under the next note, or null. */
	public String getFeedback()
	{
		return feedback;
	}

	public boolean isFeedbackError()
	{
		return feedbackIsError;
	}

	public boolean hasSong()
	{
		return song != null && song.size() > 0;
	}

	public boolean isFinished()
	{
		return hasSong() && position >= song.size();
	}

	/** The note to play next, or null when there is no song or the song is finished. */
	public ShellNote nextNote()
	{
		return hasSong() ? song.noteAt(position) : null;
	}

	/**
	 * How many times in a row the next shell must be clicked before the note changes.
	 * 0 when there is no next note.
	 */
	public int nextNoteRepeat()
	{
		return hasSong() ? song.repeatCountAt(position) : 0;
	}
}

package com.shellsongs;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Outlines the shell that should be played next in the inventory and writes on it how many
 * times in a row it has to be played.
 */
class ShellHighlightOverlay extends WidgetItemOverlay
{
	private static final Stroke OUTLINE = new BasicStroke(2f);
	private static final int BADGE_PADDING = 2;

	private final ShellSongsPlugin plugin;
	private final ShellSongsConfig config;

	@Inject
	ShellHighlightOverlay(ShellSongsPlugin plugin, ShellSongsConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.highlightInventory())
		{
			return;
		}

		PlaybackState state = plugin.getState();
		ShellNote next = state.nextNote();
		if (next == null || next.getItemId() != itemId)
		{
			return;
		}

		Rectangle bounds = widgetItem.getCanvasBounds();
		if (bounds == null)
		{
			return;
		}

		Color color = config.highlightColor();
		Stroke oldStroke = graphics.getStroke();
		Font oldFont = graphics.getFont();
		Object oldAa = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		// Outline
		graphics.setStroke(OUTLINE);
		graphics.setColor(color);
		graphics.drawRoundRect(bounds.x - 1, bounds.y - 1, bounds.width + 1, bounds.height + 1, 6, 6);

		// Click-count badge in the bottom-right corner of the item
		int repeat = state.nextNoteRepeat();
		if (repeat > 0)
		{
			String text = "x" + repeat;
			graphics.setFont(FontManager.getRunescapeBoldFont());
			FontMetrics fm = graphics.getFontMetrics();
			int textWidth = fm.stringWidth(text);
			int badgeWidth = textWidth + BADGE_PADDING * 2;
			int badgeHeight = fm.getAscent() + BADGE_PADDING;
			int bx = bounds.x + bounds.width - badgeWidth;
			int by = bounds.y + bounds.height - badgeHeight;

			graphics.setColor(new Color(0, 0, 0, 190));
			graphics.fillRoundRect(bx, by, badgeWidth, badgeHeight, 4, 4);
			graphics.setColor(color);
			graphics.drawString(text, bx + BADGE_PADDING, by + fm.getAscent() - 1);
		}

		graphics.setFont(oldFont);
		graphics.setStroke(oldStroke);
		if (oldAa != null)
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, oldAa);
		}
	}
}

package com.shellsongs;

import java.util.Locale;

/**
 * The seven musical shells rewarded by Crab Quest.
 * <p>
 * Item IDs are taken from the Old School RuneScape Wiki (8 September 2026 update).
 * They are hard-coded here because the RuneLite {@code ItemID} constants did not yet
 * include these items when this plugin was written.
 */
public enum ShellNote
{
	C("C", 34591),
	D("D", 34592),
	E("E", 34593),
	F("F", 34594),
	G("G", 34595),
	A("A", 34596),
	A_SHARP("A#", 34597);

	/** The packed "Shell collection" item that unpacks into the seven shells. */
	public static final int SHELL_COLLECTION_ITEM_ID = 34589;

	/** The inventory menu option that plays the shell. */
	public static final String SOUND_OPTION = "Sound";

	private final String label;
	private final int itemId;

	ShellNote(String label, int itemId)
	{
		this.label = label;
		this.itemId = itemId;
	}

	/** Short musical name, e.g. {@code A#}. */
	public String getLabel()
	{
		return label;
	}

	/** In-game item name, e.g. {@code Shell A#}. */
	public String getShellName()
	{
		return "Shell " + label;
	}

	public int getItemId()
	{
		return itemId;
	}

	/**
	 * @return the note for the given item id, or {@code null} if the item is not a musical shell
	 */
	public static ShellNote fromItemId(int itemId)
	{
		for (ShellNote note : values())
		{
			if (note.itemId == itemId)
			{
				return note;
			}
		}
		return null;
	}

	/**
	 * @return true if the item is one of the seven musical shells or the packed Shell collection
	 */
	public static boolean isShellItem(int itemId)
	{
		return itemId == SHELL_COLLECTION_ITEM_ID || fromItemId(itemId) != null;
	}

	/**
	 * Parses a note token such as {@code C}, {@code a}, {@code A#}, {@code A♯} or {@code Bb}.
	 *
	 * @return the matching note, or {@code null} if the token is not recognised
	 */
	public static ShellNote parse(String token)
	{
		if (token == null)
		{
			return null;
		}

		String t = token.trim().toUpperCase(Locale.ROOT)
			.replace('♯', '#')
			.replace('♭', 'b');

		switch (t)
		{
			case "C":
				return C;
			case "D":
				return D;
			case "E":
				return E;
			case "F":
				return F;
			case "G":
				return G;
			case "A":
				return A;
			case "A#":
			case "AS":
			case "ASHARP":
			case "A-SHARP":
			case "BB":
			case "Bb":
			case "BFLAT":
			case "B-FLAT":
				return A_SHARP;
			default:
				return null;
		}
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.shellsongs;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(ShellSongsConfig.GROUP)
public interface ShellSongsConfig extends Config
{
	String GROUP = "shellsongs";
	String KEY_CUSTOM_SONGS = "customSongs";
	String KEY_LOOP = "loopSong";

	@ConfigSection(
		name = "Playing",
		description = "How the plugin follows along while you play",
		position = 0
	)
	String playingSection = "playing";

	@ConfigSection(
		name = "Display",
		description = "On-screen overlay and inventory highlight",
		position = 1
	)
	String displaySection = "display";

	@ConfigSection(
		name = "Custom songs",
		description = "Add your own songs to the list",
		position = 2
	)
	String customSection = "custom";

	@ConfigItem(
		keyName = "autoAdvance",
		name = "Follow along automatically",
		description = "Move to the next note when you click 'Sound' on the correct shell",
		section = playingSection,
		position = 0
	)
	default boolean autoAdvance()
	{
		return true;
	}

	@ConfigItem(
		keyName = "advanceOnAnyShell",
		name = "Advance on wrong notes too",
		description = "Move to the next note even when you play a different shell than expected",
		section = playingSection,
		position = 1
	)
	default boolean advanceOnAnyShell()
	{
		return false;
	}

	@ConfigItem(
		keyName = KEY_LOOP,
		name = "Loop song",
		description = "Go straight back to the first note after the last one, so short songs keep playing",
		section = playingSection,
		position = 2
	)
	default boolean loopSong()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show next-note overlay",
		description = "Show the song title and the upcoming notes in an on-screen overlay",
		section = displaySection,
		position = 0
	)
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "onlyShowWithShells",
		name = "Only show overlay with shells",
		description = "Hide the overlay unless a musical shell or the Shell collection is in your inventory",
		section = displaySection,
		position = 1
	)
	default boolean onlyShowWithShells()
	{
		return true;
	}

	@Range(min = 1, max = 16)
	@ConfigItem(
		keyName = "overlayNoteCount",
		name = "Upcoming notes in overlay",
		description = "How many notes after the next one to show in the overlay",
		section = displaySection,
		position = 2
	)
	default int overlayNoteCount()
	{
		return 6;
	}

	@ConfigItem(
		keyName = "highlightInventory",
		name = "Highlight next shell",
		description = "Draw an outline around the shell you should play next in your inventory",
		section = displaySection,
		position = 3
	)
	default boolean highlightInventory()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightColor",
		name = "Highlight colour",
		description = "Colour of the inventory outline",
		section = displaySection,
		position = 4
	)
	default Color highlightColor()
	{
		return new Color(220, 138, 0);
	}

	@ConfigItem(
		keyName = KEY_CUSTOM_SONGS,
		name = "Custom songs",
		description = "One song per line, for example:  My Song: E D C | E D C | C C C C D D D D | E D C"
			+ "  Notes are C D E F G A A# (Bb also works). Use | to start a new line in the panel.",
		section = customSection,
		position = 0
	)
	default String customSongs()
	{
		return "";
	}
}

package com.shellsongs;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Small on-screen box showing the selected song, the next note and the notes after it.
 * <p>
 * Hidden while no song is selected and, by default, while there are no shells in the inventory.
 * Right-clicking it offers "Close", which clears the selected song.
 */
class ShellSongsOverlay extends OverlayPanel
{
	static final String CLOSE_OPTION = "Close";

	private final ShellSongsPlugin plugin;
	private final ShellSongsConfig config;

	@Inject
	ShellSongsOverlay(ShellSongsPlugin plugin, ShellSongsConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, CLOSE_OPTION, "Shell Songs", e -> plugin.stopSong());
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay())
		{
			return null;
		}
		if (config.onlyShowWithShells() && !plugin.hasShellsInInventory())
		{
			return null;
		}

		PlaybackState state = plugin.getState();
		if (!state.hasSong())
		{
			return null;
		}

		Song song = state.getSong();
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(song.getTitle())
			.color(Color.WHITE)
			.build());

		if (state.isFinished())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Song complete!")
				.leftColor(ColorScheme.PROGRESS_COMPLETE_COLOR)
				.build());
			return super.render(graphics);
		}

		ShellNote next = state.nextNote();
		int repeat = state.nextNoteRepeat();
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Next")
			.right(repeat > 1 ? next.getShellName() + "  x" + repeat : next.getShellName())
			.rightColor(ColorScheme.BRAND_ORANGE)
			.build());

		List<ShellNote> notes = song.getNotes();
		int from = state.getPosition() + repeat;
		int to = Math.min(notes.size(), from + config.overlayNoteCount());
		if (from < to)
		{
			StringBuilder upcoming = new StringBuilder();
			for (int i = from; i < to; i++)
			{
				if (upcoming.length() > 0)
				{
					upcoming.append(' ');
				}
				upcoming.append(notes.get(i).getLabel());
			}
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Then")
				.right(upcoming.toString())
				.build());
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Note")
			.right((state.getPosition() + 1) + " / " + song.size())
			.leftColor(ColorScheme.LIGHT_GRAY_COLOR)
			.rightColor(ColorScheme.LIGHT_GRAY_COLOR)
			.build());

		return super.render(graphics);
	}
}

package com.shellsongs;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Insets;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Sidebar panel: pick a song, see the next shell to play, and follow the whole song note by note.
 * All methods must be called on the Swing event thread.
 */
class ShellSongsPanel extends PluginPanel
{
	private static final String NO_SONG = "-";
	private static final String HTML_WIDTH = "<html><body style='width: 190px'>";

	private final ShellSongsPlugin plugin;

	private final JComboBox<Song> songBox = new JComboBox<>();
	private final JLabel nextNoteLabel = new JLabel(NO_SONG, SwingConstants.CENTER);
	private final JLabel nextShellLabel = new JLabel("Pick a song", SwingConstants.CENTER);
	private final JLabel repeatLabel = new JLabel(" ", SwingConstants.CENTER);
	private final JLabel progressLabel = new JLabel(" ", SwingConstants.CENTER);
	private final JCheckBox loopBox = new JCheckBox("Loop song");
	private final JLabel feedbackLabel = new JLabel(" ", SwingConstants.CENTER);
	private final JLabel errorsLabel = new JLabel();
	private final NoteSheetComponent sheet;

	/** Set while the combo box or loop box is being updated from code so their listeners do not fire. */
	private boolean updatingSongs;
	private boolean updatingLoop;

	ShellSongsPanel(ShellSongsPlugin plugin)
	{
		super();
		this.plugin = plugin;

		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setLayout(new BorderLayout());

		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);

		// Title
		JLabel title = new JLabel("Shell Songs");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		content.add(title);
		content.add(Box.createVerticalStrut(8));

		// Song picker
		songBox.setFocusable(false);
		songBox.setAlignmentX(Component.LEFT_ALIGNMENT);
		songBox.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		songBox.setPreferredSize(new Dimension(PANEL_WIDTH - 2 * BORDER_OFFSET, 28));
		songBox.addActionListener(e ->
		{
			if (updatingSongs)
