		// Help text
		JLabel help = new JLabel(HTML_WIDTH
			+ "Play the highlighted shell. The number on it is how many times in a row to play it. "
			+ "The panel moves on when you play the right shell. "
			+ "Click any note above to jump to it. "
			+ "Stop clears the song and hides the overlay. "
			+ "Add your own songs in the plugin settings.</body></html>");
		help.setFont(FontManager.getRunescapeSmallFont());
		help.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		help.setAlignmentX(Component.LEFT_ALIGNMENT);
		content.add(help);

		add(content, BorderLayout.NORTH);
	}

	private static JButton makeButton(String text, Runnable action)
	{
		JButton button = new JButton(text);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setMargin(new Insets(2, 4, 2, 4));
		button.setFocusable(false);
		button.addActionListener(e -> action.run());
		return button;
	}

	/** Reflects the "Loop song" setting in the checkbox without firing its listener. */
	void setLoop(boolean loop)
	{
		updatingLoop = true;
		try
		{
			loopBox.setSelected(loop);
		}
		finally
		{
			updatingLoop = false;
		}
	}

	/** Replaces the song list, keeping {@code selected} selected if it is present. */
	void setSongs(List<Song> songs, Song selected, List<String> errors)
	{
		updatingSongs = true;
		try
		{
			songBox.removeAllItems();
			for (Song song : songs)
			{
				songBox.addItem(song);
			}
			if (selected == null)
			{
				songBox.setSelectedIndex(-1);
			}
			else
			{
				songBox.setSelectedItem(selected);
			}
		}
		finally
		{
			updatingSongs = false;
		}

		if (errors.isEmpty())
		{
			errorsLabel.setVisible(false);
			errorsLabel.setText("");
		}
		else
		{
			StringBuilder sb = new StringBuilder(HTML_WIDTH).append("<b>Custom songs:</b>");
			for (String error : errors)
			{
				sb.append("<br>").append(escapeHtml(error));
			}
			sb.append("</body></html>");
			errorsLabel.setText(sb.toString());
			errorsLabel.setVisible(true);
		}
	}

	/** Redraws everything from the current playback state. */
	void update(PlaybackState state)
	{
		Song song = state.getSong();

		if (song != songBox.getSelectedItem())
		{
			updatingSongs = true;
			try
			{
				if (song == null)
				{
					songBox.setSelectedIndex(-1);
				}
				else
				{
					songBox.setSelectedItem(song);
				}
			}
			finally
			{
				updatingSongs = false;
			}
		}

		if (!state.hasSong())
		{
			nextNoteLabel.setText(NO_SONG);
			nextNoteLabel.setForeground(ColorScheme.BRAND_ORANGE);
			nextShellLabel.setText("Pick a song");
			repeatLabel.setText(" ");
			progressLabel.setText(" ");
			feedbackLabel.setText(" ");
			sheet.setSong(null);
			revalidate();
			repaint();
			return;
		}

		sheet.setSong(song);
		sheet.setPosition(state.getPosition(), state.nextNoteRepeat());

		if (state.isFinished())
		{
			nextNoteLabel.setText("Done");
			nextNoteLabel.setForeground(ColorScheme.PROGRESS_COMPLETE_COLOR);
			nextShellLabel.setText("Song complete!");
			repeatLabel.setText(" ");
			progressLabel.setText("Play any shell to start again");
		}
		else
		{
			ShellNote next = state.nextNote();
			int repeat = state.nextNoteRepeat();
			nextNoteLabel.setText(next.getLabel());
			nextNoteLabel.setForeground(ColorScheme.BRAND_ORANGE);
			nextShellLabel.setText(next.getShellName());
			repeatLabel.setText(repeat > 1 ? "Click " + repeat + " times in a row" : "Click once");
			progressLabel.setText("Note " + (state.getPosition() + 1) + " of " + song.size());
		}

		String feedback = state.getFeedback();
		feedbackLabel.setText(feedback == null ? " " : feedback);
		feedbackLabel.setForeground(state.isFeedbackError()
			? ColorScheme.PROGRESS_ERROR_COLOR
			: ColorScheme.LIGHT_GRAY_COLOR);

		revalidate();
		repaint();
	}

	private static String escapeHtml(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.shellsongs;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

/**
 * Shell Songs: a song book for the seven musical shells from Crab Quest.
 * <p>
 * The plugin only watches which shell the player clicks "Sound" on and moves a cursor through the
 * selected song. It never plays shells, sends input, or changes menus.
 */
@Slf4j
@PluginDescriptor(
	name = "Shell Songs",
	description = "Shows which musical shells from Crab Quest to play, note by note, for a library of songs",
	tags = {"shell", "shells", "music", "song", "songs", "notes", "crab", "crab quest", "instrument", "sailing"}
)
public class ShellSongsPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ShellSongsConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ShellSongsOverlay overlay;

	@Inject
	private ShellHighlightOverlay highlightOverlay;

	private ShellSongsPanel panel;
	private NavigationButton navButton;

	// Playback state. Guarded by "this" because it is touched from the client thread
	// (menu clicks, overlay rendering) and from the Swing thread (panel buttons).
	private Song currentSong;
	private int position;
	private String feedback;
	private boolean feedbackIsError;

	/** True while a musical shell or the packed Shell collection is in the inventory. */
	private volatile boolean shellsInInventory;

	@Override
	protected void startUp()
	{
		panel = new ShellSongsPanel(this);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Shell Songs")
			.icon(icon)
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		overlayManager.add(overlay);
		overlayManager.add(highlightOverlay);

		clientThread.invoke(this::refreshShellsInInventory);
		reloadSongs();
		final boolean loop = config.loopSong();
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.setLoop(loop);
			}
		});
		log.debug("Shell Songs started");
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(highlightOverlay);
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;
		shellsInInventory = false;

		synchronized (this)
		{
			currentSong = null;
			position = 0;
			feedback = null;
			feedbackIsError = false;
		}
		log.debug("Shell Songs stopped");
	}

	@Provides
	ShellSongsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ShellSongsConfig.class);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!ShellSongsConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if (ShellSongsConfig.KEY_CUSTOM_SONGS.equals(event.getKey()))
		{
			reloadSongs();
		}
		else if (ShellSongsConfig.KEY_LOOP.equals(event.getKey()))
		{
			final boolean loop = config.loopSong();
			SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.setLoop(loop);
				}
			});
		}
	}

	/** Called by the panel's Loop checkbox. Writes the setting so it persists and stays in sync. */
	void setLoop(boolean loop)
	{
		configManager.setConfiguration(ShellSongsConfig.GROUP, ShellSongsConfig.KEY_LOOP, loop);
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!config.autoAdvance() || !event.isItemOp())
		{
			return;
		}
		if (!ShellNote.SOUND_OPTION.equals(event.getMenuOption()))
		{
			return;
		}

		ShellNote played = ShellNote.fromItemId(event.getItemId());
		if (played == null)
		{
			return;
		}

		onShellPlayed(played, config.advanceOnAnyShell(), config.loopSong());
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV)
		{
			shellsInInventory = containsShells(event.getItemContainer());
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			shellsInInventory = false;
		}
	}

	/** Reads the inventory directly. Must run on the client thread. */
	private void refreshShellsInInventory()
	{
		shellsInInventory = containsShells(client.getItemContainer(InventoryID.INV));
	}

	/** @return whether a musical shell or the packed Shell collection is in the inventory */
	boolean hasShellsInInventory()
	{
		return shellsInInventory;
	}

	private static boolean containsShells(ItemContainer container)
	{
		return container != null && containsShells(container.getItems());
	}

	/** @return true if any of the items is a musical shell or the packed Shell collection */
	static boolean containsShells(Item[] items)
	{
		if (items == null)
		{
			return false;
		}
		for (Item item : items)
		{
			if (ShellNote.isShellItem(item.getId()))
			{
				return true;
			}
		}
		return false;
	}

	// ---- State changes. Safe to call from any thread. ----

	/** Rebuilds the song list from the built-in library plus the custom-songs setting. */
	private void reloadSongs()
	{
		final List<String> errors = new ArrayList<>();
		final List<Song> loaded = SongLibrary.all(config.customSongs(), errors);

		final Song selected;
		synchronized (this)
		{
			// Keep the current song selected if a song with the same title still exists.
			Song keep = null;
			if (currentSong != null)
			{
				for (Song song : loaded)
				{
					if (song.getTitle().equals(currentSong.getTitle()) && song.isCustom() == currentSong.isCustom())
					{
						keep = song;
						break;
					}
				}
			}

			if (keep == null)
			{
				currentSong = null;
				position = 0;
				feedback = null;
				feedbackIsError = false;
			}
			else if (keep != currentSong)
			{
				// Same title but the notes may have been edited; clamp the cursor.
				currentSong = keep;
				position = Math.min(position, keep.size());
			}
			selected = currentSong;
		}

		final PlaybackState state = getState();
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.setSongs(loaded, selected, errors);
				panel.update(state);
			}
		});
	}

	void selectSong(Song song)
	{
		synchronized (this)
		{
			currentSong = song;
			position = 0;
			feedback = null;
			feedbackIsError = false;
		}
		refreshPanel();
	}

	/** Clears the selected song, which also hides the overlay and the inventory highlight. */
	void stopSong()
	{
		selectSong(null);
	}

	void restartSong()
	{
		synchronized (this)
		{
			position = 0;
			feedback = null;
			feedbackIsError = false;
		}
		refreshPanel();
	}

	void nextNote()
	{
		synchronized (this)
		{
			if (currentSong != null && position < currentSong.size())
			{
				position++;
			}
			feedback = null;
			feedbackIsError = false;
		}
		refreshPanel();
	}

	void previousNote()
	{
		synchronized (this)
		{
			if (position > 0)
			{
				position--;
			}
			feedback = null;
			feedbackIsError = false;
		}
		refreshPanel();
	}

	void jumpToNote(int index)
	{
		synchronized (this)
		{
			if (currentSong != null)
			{
				position = Math.max(0, Math.min(index, currentSong.size()));
			}
			feedback = null;
			feedbackIsError = false;
		}
		refreshPanel();
	}

	/**
	 * Called when the player clicks "Sound" on a musical shell.
	 *
	 * @param played            the shell that was played
	 * @param advanceOnAnyShell whether a wrong note should still move the cursor forward
	 * @param loop              whether finishing the song should jump straight back to the start
	 */
	void onShellPlayed(ShellNote played, boolean advanceOnAnyShell, boolean loop)
	{
		synchronized (this)
		{
			if (currentSong == null || currentSong.size() == 0)
			{
				return;
			}

			// After finishing a song, the next shell played starts it again.
			if (position >= currentSong.size())
			{
				position = 0;
			}

			ShellNote expected = currentSong.noteAt(position);
			if (played == expected || advanceOnAnyShell)
			{
				position++;
				if (played != expected)
				{
					feedback = "Played " + played.getLabel() + ", wanted " + expected.getLabel();
					feedbackIsError = true;
				}
				else if (position >= currentSong.size() && loop)
				{
					position = 0;
					feedback = "Whole song played. Looping from the top.";
					feedbackIsError = false;
				}
				else if (position >= currentSong.size())
				{
					feedback = "Nice! You played the whole song.";
					feedbackIsError = false;
				}
				else
				{
					feedback = null;
					feedbackIsError = false;
				}
			}
			else
			{
				feedback = "That was " + played.getLabel() + ", play " + expected.getLabel();
				feedbackIsError = true;
			}
		}
		refreshPanel();
	}

	/** @return an immutable snapshot of the playback state */
	synchronized PlaybackState getState()
	{
		return new PlaybackState(currentSong, position, feedback, feedbackIsError);
	}

	private void refreshPanel()
	{
		final PlaybackState state = getState();
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.update(state);
			}
		});
	}
}

package com.shellsongs;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * An immutable song: a title plus an ordered list of phrases, each phrase being a list of notes.
 * Phrases only affect how the song is displayed (line breaks); playback is over the flat note list.
 */
public final class Song
{
	private final String title;
	private final boolean custom;
	private final List<List<ShellNote>> phrases;
	private final List<ShellNote> notes;

	public Song(String title, List<List<ShellNote>> phrases, boolean custom)
	{
		this.title = title;
		this.custom = custom;

		List<List<ShellNote>> phraseCopy = new ArrayList<>();
		List<ShellNote> flat = new ArrayList<>();
		for (List<ShellNote> phrase : phrases)
		{
			if (phrase.isEmpty())
			{
				continue;
			}
			phraseCopy.add(Collections.unmodifiableList(new ArrayList<>(phrase)));
			flat.addAll(phrase);
		}
		this.phrases = Collections.unmodifiableList(phraseCopy);
		this.notes = Collections.unmodifiableList(flat);
	}

	public String getTitle()
	{
		return title;
	}

	/** True when the song came from the user's "Custom songs" setting rather than the built-in list. */
	public boolean isCustom()
	{
		return custom;
	}

	public List<List<ShellNote>> getPhrases()
	{
		return phrases;
	}

	/** Every note of the song in playing order. */
	public List<ShellNote> getNotes()
	{
		return notes;
	}

	public int size()
	{
		return notes.size();
	}

	/**
	 * @return the note at the given position, or {@code null} if the position is past the end
	 */
	public ShellNote noteAt(int position)
	{
		if (position < 0 || position >= notes.size())
		{
			return null;
		}
		return notes.get(position);
	}

	/**
	 * Counts how many times in a row the note at {@code position} repeats, including itself.
	 * For "C C C D" at position 0 this is 3; at position 3 it is 1. Past the end it is 0.
	 */
	public int repeatCountAt(int position)
	{
		ShellNote note = noteAt(position);
		if (note == null)
		{
			return 0;
		}
		int count = 1;
		while (noteAt(position + count) == note)
		{
			count++;
		}
		return count;
	}

	@Override
	public String toString()
	{
		// Used by the song drop-down.
		return custom ? title + " (custom)" : title;
	}
}

package com.shellsongs;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * The built-in song list.
 * <p>
 * The shells cover a single F-major scale without an upper octave: C D E F G A A#.
 * Every built-in song therefore fits inside that range; a few well-known tunes are transposed
 * (Old MacDonald, Au Clair de la Lune) or shortened (marked in the title) to make them fit.
 * <p>
 * Only public-domain material belongs here: nursery rhymes, folk songs, carols and classical
 * themes. Do not add songs that are still in copyright.
 */
public final class SongLibrary
{
	private static final String[] BUILT_IN = {
		"Scale practice: C D E F G A A# | A# A G F E D C",
		"Hot Cross Buns: E D C | E D C | C C C C D D D D | E D C",
		"Mary Had a Little Lamb: E D C D E E E | D D D E G G | E D C D E E E | E D D E D C",
		"Twinkle, Twinkle, Little Star: C C G G A A G | F F E E D D C | G G F F E E D | G G F F E E D | C C G G A A G | F F E E D D C",
		"Baa Baa Black Sheep: C C G G A A A A G | F F E E D D C | G G G G F F F F E E E E D | G G G G F F F F E E E E D | C C G G A A A A G | F F E E D D C",
		"London Bridge Is Falling Down: G A G F E F G | D E F | E F G | G A G F E F G | D G E C",
		"Jingle Bells (chorus): E E E | E E E | E G C D E | F F F F F E E E E D D E D G | E E E | E E E | E G C D E | F F F F F E E E E G G F D C",
		"Ode to Joy (main theme): E E F G G F E D | C C D E E D D | E E F G G F E D | C C D E D C C",
		"When the Saints Go Marching In: C E F G | C E F G | C E F G E C E D | E E D C C E G G F | E F G E C D C",
		"Old MacDonald Had a Farm: F F F C D D C | A A G G F | C F F F C D D C | A A G G F | C C F F F | C C F F F | F F F F F F F F F F F F F | F F F C D D C | A A G G F",
		"This Old Man: G E G | G E G | A G F E D E F | E F G C C C C C D E F G | G D D F E D C",
		"Oh! Susanna: C D E G G A G E | C D E E D C D | C D E G G A G E | C D E E D D C | F F A A G G E C D | C D E G G A G E | C D E E D D C",
		"Itsy Bitsy Spider: C C C D E E | E D C D E C | E E F G | G F E F G E | C C D E | E D C D E C | C C C D E E | E D C D E C",
		"Au Clair de la Lune: F F F G A G | F A G G F | F F F G A G | F A G G F | G G G G D D | G F E D C | F F F G A G | F A G G F",
		"Lightly Row: G E E | F D D | C D E F G G G | G E E | F D D | C E G G E E E | D D D D D E F | E E E E E F G | G E E | F D D | C E G G E E E",
		"Camptown Races (verse): G G E G A G E | E D | E D | G G E G A G E | D E D C",
		"Frere Jacques (first four lines): C D E C | C D E C | E F G | E F G | G A G F E C | G A G F E C",
		"Rain, Rain, Go Away: G E G G E | G G E A G E | G G E A G E | G E G G E",
		"We Wish You a Merry Christmas (chorus): C F F G F E D D | D G G A G F E C | C A A A# A G F D | C C D G E F",
		"O Christmas Tree (first lines): C F F F G A A A | G A A# E G F | C F F F G A A A | G A A# E G F",
	};

	private static final List<Song> BUILT_IN_SONGS;

	static
	{
		List<Song> songs = new ArrayList<>();
		for (String line : BUILT_IN)
		{
			try
			{
				songs.add(SongParser.parseLine(line, false));
			}
			catch (SongParser.SongFormatException ex)
			{
				// A typo in the table above is a programming error; fail loudly so tests catch it.
				throw new IllegalStateException("Built-in song is malformed: " + line, ex);
			}
		}
		BUILT_IN_SONGS = Collections.unmodifiableList(songs);
	}

	private SongLibrary()
	{
	}

	public static List<Song> builtIn()
	{
		return BUILT_IN_SONGS;
	}

	/**
	 * Builds the full song list: built-in songs followed by the user's custom songs.
	 *
	 * @param customSongsText the raw "Custom songs" config text, may be null
	 * @param errors          receives a human-readable message for every custom line that failed to parse
	 */
	public static List<Song> all(String customSongsText, List<String> errors)
	{
		List<Song> songs = new ArrayList<>(BUILT_IN_SONGS);
		songs.addAll(SongParser.parseAll(customSongsText, true, errors));
		return songs;
	}
}

package com.shellsongs;

import java.util.ArrayList;
import java.util.List;

/**
 * Parses the plain-text song format used both for the built-in library and for user-defined songs.
 * <pre>
 * Title: E D C | E D C | C C C C D D D D | E D C
 * </pre>
 * Notes are separated by spaces. A {@code |} (or a comma) starts a new phrase, which is shown on
 * its own line in the panel. Tokens {@code -} and {@code _} are ignored so users can pad rhythm.
 * Blank lines and lines starting with {@code #} are ignored.
 */
public final class SongParser
{
	private SongParser()
	{
	}

	/** Thrown when a song line cannot be understood. The message is user-facing. */
	public static final class SongFormatException extends Exception
	{
		SongFormatException(String message)
		{
			super(message);
		}
	}

	/**
	 * Parses a single song line.
	 *
	 * @throws SongFormatException if the line has no title, has no notes, or contains an unknown note
	 */
	public static Song parseLine(String line, boolean custom) throws SongFormatException
	{
		if (line == null)
		{
			throw new SongFormatException("Empty line");
		}

		int colon = line.indexOf(':');
		if (colon < 0)
		{
			throw new SongFormatException("Missing ':' between the title and the notes");
		}

		String title = line.substring(0, colon).trim();
		if (title.isEmpty())
		{
			throw new SongFormatException("Missing song title before ':'");
		}

		String body = line.substring(colon + 1);
		List<List<ShellNote>> phrases = new ArrayList<>();
		List<ShellNote> current = new ArrayList<>();

		// Treat '|' and ',' as phrase separators even when glued to a note ("E|" or "C,").
		String spaced = body.replace("|", " | ").replace(",", " , ");
		for (String token : spaced.trim().split("\\s+"))
		{
			if (token.isEmpty())
			{
				continue;
			}
			if (token.equals("|") || token.equals(","))
			{
				if (!current.isEmpty())
				{
					phrases.add(current);
					current = new ArrayList<>();
				}
				continue;
			}
			if (token.equals("-") || token.equals("_"))
			{
				continue;
			}

			ShellNote note = ShellNote.parse(token);
			if (note == null)
			{
				throw new SongFormatException("'" + title + "': unknown note '" + token
					+ "' (use C D E F G A A#)");
			}
			current.add(note);
		}
		if (!current.isEmpty())
		{
			phrases.add(current);
		}

		if (phrases.isEmpty())
		{
			throw new SongFormatException("'" + title + "': no notes after ':'");
		}

		return new Song(title, phrases, custom);
	}

	/**
	 * Parses many song lines. Lines that fail are skipped and their error message (prefixed with the
	 * 1-based line number) is added to {@code errors}.
	 */
	public static List<Song> parseAll(String text, boolean custom, List<String> errors)
	{
		List<Song> songs = new ArrayList<>();
		if (text == null)
		{
			return songs;
		}

		String[] lines = text.split("\\r?\\n");
		for (int i = 0; i < lines.length; i++)
		{
			String line = lines[i].trim();
			if (line.isEmpty() || line.startsWith("#"))
			{
				continue;
			}
			try
			{
				songs.add(parseLine(line, custom));
			}
			catch (SongFormatException ex)
			{
				errors.add("Line " + (i + 1) + ": " + ex.getMessage());
			}
		}
		return songs;
	}
}

package com.shellsongs;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class PlaybackStateTest
{
	@Test
	public void emptyStateHasNoSong()
	{
		assertFalse(PlaybackState.EMPTY.hasSong());
		assertFalse(PlaybackState.EMPTY.isFinished());
		assertNull(PlaybackState.EMPTY.nextNote());
	}

	@Test
	public void tracksNextNoteAndCompletion() throws Exception
	{
		Song song = SongParser.parseLine("Short: E D C", false);

		PlaybackState start = new PlaybackState(song, 0, null, false);
		assertTrue(start.hasSong());
		assertEquals(ShellNote.E, start.nextNote());
		assertFalse(start.isFinished());

		PlaybackState done = new PlaybackState(song, 3, "done", false);
		assertTrue(done.isFinished());
		assertNull(done.nextNote());
		assertEquals("done", done.getFeedback());
	}
}

package com.shellsongs;

import java.awt.Dimension;
import java.util.Collections;
import java.util.List;
import javax.swing.SwingUtilities;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * Builds the real sidebar panel headlessly and pushes every kind of state through it, so layout or
 * painting mistakes fail here instead of inside the client.
 */
public class ShellSongsPanelTest
{
	@BeforeClass
	public static void headless()
	{
		System.setProperty("java.awt.headless", "true");
	}

	@Test
	public void panelSurvivesEveryState() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			ShellSongsPlugin plugin = new ShellSongsPlugin();
			ShellSongsPanel panel = new ShellSongsPanel(plugin);
			List<Song> songs = SongLibrary.builtIn();
			Song first = songs.get(0);

			panel.setSongs(songs, first, Collections.emptyList());
			panel.setLoop(true);
			panel.setLoop(false);
			panel.update(new PlaybackState(first, 0, null, false));
			panel.setSize(225, 800);
			panel.doLayout();

			panel.update(new PlaybackState(first, 3, "That was C, play D", true));
			panel.update(new PlaybackState(first, first.size(), "Nice!", false));
			panel.update(PlaybackState.EMPTY);
			panel.setSongs(songs, null, Collections.singletonList("Line 2: 'Bad': unknown note 'B'"));

			// Switching to the longest song must not throw and must give the sheet real height.
			Song longest = songs.get(0);
			for (Song song : songs)
			{
				if (song.size() > longest.size())
				{
					longest = song;
				}
			}
			panel.update(new PlaybackState(longest, 1, null, false));
		});
	}

	@Test
	public void noteSheetWrapsLongPhrases() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			NoteSheetComponent sheet = new NoteSheetComponent(i ->
			{
			});
			Song song = null;
			try
			{
				// 20 notes in one phrase: wider than the sidebar, so it must wrap onto a second row.
				song = SongParser.parseLine("Long: C C C C C C C C C C C C C C C C C C C C", false);
			}
			catch (SongParser.SongFormatException e)
			{
				throw new AssertionError(e);
			}

			sheet.setSong(song);
			Dimension pref = sheet.getPreferredSize();
			assertEquals(213, pref.width);
			assertTrue("expected at least two rows, got height " + pref.height, pref.height > 22 * 2);

			sheet.setSong(null);
			assertEquals(0, sheet.getPreferredSize().height);
		});
	}
}

package com.shellsongs;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import net.runelite.api.Item;
import org.junit.Before;
import org.junit.Test;

/**
 * Exercises the follow-along state machine without RuneLite's injector; only the plain methods
 * that the panel and the menu-click handler call are used.
 */
public class ShellSongsPluginStateTest
{
	private ShellSongsPlugin plugin;
	private Song song;

	@Before
	public void setUp() throws Exception
	{
		plugin = new ShellSongsPlugin();
		song = SongParser.parseLine("Test: E D C", false);
		plugin.selectSong(song);
	}

	@Test
	public void stopClearsTheSong()
	{
		plugin.onShellPlayed(ShellNote.E, false, false);
		plugin.stopSong();

		PlaybackState state = plugin.getState();
		assertFalse(state.hasSong());
		assertNull(state.getSong());
		assertEquals(0, state.getPosition());
		assertNull(state.nextNote());
		assertNull(state.getFeedback());
	}

	@Test
	public void shellsAreDetectedAmongInventoryItems()
	{
		assertFalse(ShellSongsPlugin.containsShells((Item[]) null));
		assertFalse(ShellSongsPlugin.containsShells(new Item[0]));
		assertFalse(ShellSongsPlugin.containsShells(items(new Item(995, 1), new Item(-1, 0))));
		assertTrue(ShellSongsPlugin.containsShells(items(new Item(995, 1), new Item(ShellNote.G.getItemId(), 1))));
		assertTrue(ShellSongsPlugin.containsShells(items(new Item(ShellNote.SHELL_COLLECTION_ITEM_ID, 1))));
	}

	private static Item[] items(Item... items)
	{
		return items;
	}

	@Test
	public void startsAtFirstNote()
	{
		PlaybackState state = plugin.getState();
		assertEquals(song, state.getSong());
		assertEquals(0, state.getPosition());
		assertEquals(ShellNote.E, state.nextNote());
		assertNull(state.getFeedback());
	}

	@Test
	public void correctNotesAdvanceAndFinish()
	{
		plugin.onShellPlayed(ShellNote.E, false, false);
		assertEquals(ShellNote.D, plugin.getState().nextNote());

		plugin.onShellPlayed(ShellNote.D, false, false);
		plugin.onShellPlayed(ShellNote.C, false, false);

		PlaybackState done = plugin.getState();
		assertTrue(done.isFinished());
		assertFalse(done.isFeedbackError());
		assertTrue(done.getFeedback().contains("whole song"));
	}

	@Test
	public void wrongNoteDoesNotAdvanceByDefault()
	{
		plugin.onShellPlayed(ShellNote.A_SHARP, false, false);

		PlaybackState state = plugin.getState();
		assertEquals(0, state.getPosition());
		assertTrue(state.isFeedbackError());
		assertTrue(state.getFeedback().contains("A#"));
		assertTrue(state.getFeedback().contains("E"));
	}

	@Test
	public void wrongNoteAdvancesWhenConfigured()
	{
		plugin.onShellPlayed(ShellNote.A_SHARP, true, false);

		PlaybackState state = plugin.getState();
		assertEquals(1, state.getPosition());
		assertTrue(state.isFeedbackError());
	}

	@Test
	public void playingAfterFinishRestartsSong()
	{
		plugin.jumpToNote(song.size());
		assertTrue(plugin.getState().isFinished());

		plugin.onShellPlayed(ShellNote.E, false, false);
		assertEquals(1, plugin.getState().getPosition());
	}

	@Test
	public void transportButtonsClampToSong()
	{
		plugin.previousNote();
		assertEquals(0, plugin.getState().getPosition());

		plugin.nextNote();
		plugin.nextNote();
		plugin.nextNote();
		plugin.nextNote();
		assertEquals(song.size(), plugin.getState().getPosition());

		plugin.jumpToNote(99);
		assertEquals(song.size(), plugin.getState().getPosition());
		plugin.jumpToNote(-5);
		assertEquals(0, plugin.getState().getPosition());

		plugin.nextNote();
		plugin.restartSong();
		assertEquals(0, plugin.getState().getPosition());
	}

	@Test
	public void loopingJumpsBackToStartAfterLastNote()
	{
		plugin.onShellPlayed(ShellNote.E, false, true);
		plugin.onShellPlayed(ShellNote.D, false, true);
		plugin.onShellPlayed(ShellNote.C, false, true);

		PlaybackState state = plugin.getState();
		assertFalse(state.isFinished());
		assertEquals(0, state.getPosition());
		assertEquals(ShellNote.E, state.nextNote());
		assertFalse(state.isFeedbackError());
		assertTrue(state.getFeedback().contains("Looping"));
	}

	@Test
	public void repeatCountFollowsRunsOfTheSameShell() throws Exception
	{
		Song run = SongParser.parseLine("Run: C C C D", false);
		plugin.selectSong(run);

		assertEquals(3, plugin.getState().nextNoteRepeat());
		plugin.onShellPlayed(ShellNote.C, false, false);
		assertEquals(2, plugin.getState().nextNoteRepeat());
		plugin.onShellPlayed(ShellNote.C, false, false);
		assertEquals(1, plugin.getState().nextNoteRepeat());
		plugin.onShellPlayed(ShellNote.C, false, false);
		assertEquals(ShellNote.D, plugin.getState().nextNote());
		assertEquals(1, plugin.getState().nextNoteRepeat());
		plugin.onShellPlayed(ShellNote.D, false, false);
		assertEquals(0, plugin.getState().nextNoteRepeat());
	}

	@Test
	public void shellPlayedWithoutSongIsIgnored()
	{
		plugin.selectSong(null);
		plugin.onShellPlayed(ShellNote.C, false, false);
		assertFalse(plugin.getState().hasSong());
	}
}

